82	// RenderOptions configure SQL rendering.
83	type RenderOptions struct {
84		Dialect           DialectName
85		PlaceholderOffset int
86		DisableNullChecks bool
87	}
88	
89	// Statement contains the rendered SQL fragment and its args.
90	type Statement struct {
91		SQL  string
92		Args []any
93	}
94	
95	// Render converts the program into a dialect-specific SQL fragment.
96	func (p *Program) Render(opts RenderOptions) (Statement, error) {
97		renderer := newRenderer(p.schema, opts)
98		return renderer.Render(p.condition)
99	}
