10	// parseContext carries the schema plus the frozen evaluation time used to fold
11	// the `now` variable into a constant. Freezing once per compile guarantees a
12	// single filter observes a single instant.
13	type parseContext struct {
14		schema Schema
15		now    time.Time
16	}
17	
18	func buildCondition(expr *exprv1.Expr, pc parseContext) (Condition, error) {
19		switch v := expr.ExprKind.(type) {
20		case *exprv1.Expr_CallExpr:
21			return buildCallCondition(v.CallExpr, pc)
22		case *exprv1.Expr_ConstExpr:
23			val, err := getConstValue(expr)
24			if err != nil {
25				return nil, err
26			}
27			if v, ok := val.(bool); ok {
28				return &ConstantCondition{Value: v}, nil
29			}
30			return nil, errors.New("filter must evaluate to a boolean value")
31		case *exprv1.Expr_IdentExpr:
32			name := v.IdentExpr.GetName()
33			field, ok := pc.schema.Field(name)
34			if !ok {
35				return nil, errors.Errorf("unknown identifier %q", name)
36			}
37			if field.Type != FieldTypeBool {
38				return nil, errors.Errorf("identifier %q is not boolean", name)
39			}
40			return &FieldPredicateCondition{Field: name}, nil
41		case *exprv1.Expr_ComprehensionExpr:
42			return buildComprehensionCondition(v.ComprehensionExpr, pc.schema)
43		default:
44			return nil, errors.New("unsupported top-level expression")
45		}
46	}
47	
48	func buildCallCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
49		switch call.Function {
50		case "_&&_":
51			if len(call.Args) != 2 {
52				return nil, errors.New("logical AND expects two arguments")
53			}
54			left, err := buildCondition(call.Args[0], pc)
55			if err != nil {
56				return nil, err
57			}
58			right, err := buildCondition(call.Args[1], pc)
59			if err != nil {
60				return nil, err
61			}
62			return &LogicalCondition{
63				Operator: LogicalAnd,
64				Left:     left,
65				Right:    right,
66			}, nil
67		case "_||_":
68			if len(call.Args) != 2 {
69				return nil, errors.New("logical OR expects two arguments")
70			}
71			left, err := buildCondition(call.Args[0], pc)
72			if err != nil {
73				return nil, err
74			}
75			right, err := buildCondition(call.Args[1], pc)
76			if err != nil {
77				return nil, err
78			}
79			return &LogicalCondition{
80				Operator: LogicalOr,
81				Left:     left,
82				Right:    right,
83			}, nil
84		case "!_":
85			if len(call.Args) != 1 {
86				return nil, errors.New("logical NOT expects one argument")
87			}
88			child, err := buildCondition(call.Args[0], pc)
89			if err != nil {
90				return nil, err
91			}
92			return &NotCondition{Expr: child}, nil
93		case "_==_", "_!=_", "_<_", "_>_", "_<=_", "_>=_":
94			return buildComparisonCondition(call, pc)
95		case "@in":
96			return buildInCondition(call, pc)
97		case "contains":
98			return buildTextMatchCondition(call, pc.schema, TextMatchContains)
99		case "startsWith":
100			return buildTextMatchCondition(call, pc.schema, TextMatchPrefix)
101		case "endsWith":
102			return buildTextMatchCondition(call, pc.schema, TextMatchSuffix)
103		case "matches":
104			return buildMatchesCondition(call, pc.schema)
105		case "sets.contains", "sets.intersects", "sets.equivalent":
106			return buildSetCondition(call, pc)
107		default:
108			val, ok, err := evaluateBool(call)
109			if err != nil {
110				return nil, err
111			}
112			if ok {
113				return &ConstantCondition{Value: val}, nil
114			}
115			return nil, errors.Errorf("unsupported call expression %q", call.Function)
116		}
117	}
