516	func (r *renderer) renderScalarInCondition(field Field, values []ValueExpr) (renderResult, error) {
517		placeholders := make([]string, 0, len(values))
518	
519		for _, v := range values {
520			lit, err := expectLiteral(v)
521			if err != nil {
522				return renderResult{}, err
523			}
524			switch field.Type {
525			case FieldTypeString:
526				str, ok := lit.(string)
527				if !ok {
528					return renderResult{}, errors.Errorf("field %q expects string values", field.Name)
529				}
530				placeholders = append(placeholders, r.addArg(str))
531			case FieldTypeInt:
532				num, err := toInt64(lit)
533				if err != nil {
534					return renderResult{}, err
535				}
536				placeholders = append(placeholders, r.addArg(num))
537			default:
538				return renderResult{}, errors.Errorf("field %q does not support IN() comparisons", field.Name)
539			}
540		}
541	
542		column := field.columnExpr(r.dialect)
543		return renderResult{
544			sql: fmt.Sprintf("%s IN (%s)", column, strings.Join(placeholders, ",")),
545		}, nil
546	}
